<?php
require 'config.php';require_login();$pageTitle='Attendance';$active='attendance';$date=$_GET['date']??date('Y-m-d');
if($_SERVER['REQUEST_METHOD']==='POST'){$date=$_POST['attendance_date']??date('Y-m-d');$statuses=$_POST['status']??[];try{$conn->begin_transaction();$s=$conn->prepare('INSERT INTO attendance(student_id,attendance_date,status) VALUES(?,?,?) ON DUPLICATE KEY UPDATE status=VALUES(status)');foreach($statuses as $id=>$status){$id=(int)$id;if(!in_array($status,['Present','Absent'],true))continue;$s->bind_param('iss',$id,$date,$status);$s->execute();}$conn->commit();flash('success','Attendance saved for '.date('d M Y',strtotime($date)).'.');header('Location: attendance.php?date='.urlencode($date));exit;}catch(Throwable $e){$conn->rollback();flash('error','Unable to save attendance.');}}
$s=$conn->prepare('SELECT st.id,st.register_number,st.name,st.department,a.status FROM students st LEFT JOIN attendance a ON a.student_id=st.id AND a.attendance_date=? ORDER BY st.name');$s->bind_param('s',$date);$s->execute();$rows=$s->get_result();require 'includes/header.php';?>
<div class="heading"><div><p class="eyebrow">DAILY REGISTER</p><h1>Attendance management</h1><p class="muted">Mark and review student attendance by date.</p></div></div><section class="card"><div class="cardhead"><div><h2>Attendance register</h2><p class="muted">Choose Present or Absent for each student, then save.</p></div><form method="get" class="dateform"><input type="date" name="date" value="<?=e($date)?>" required><button class="btn secondary">Load date</button></form></div><form method="post"><input type="hidden" name="attendance_date" value="<?=e($date)?>"><div class="tablewrap"><table><thead><tr><th>STUDENT</th><th>DEPARTMENT</th><th>ATTENDANCE STATUS</th></tr></thead><tbody><?php if($rows->num_rows):while($r=$rows->fetch_assoc()):$v=$r['status']??'Present';?><tr><td><b><?=e($r['name'])?></b><small><?=e($r['register_number'])?></small></td><td><?=e($r['department'])?></td><td><div class="choices"><label><input type="radio" name="status[<?=$r['id']?>]" value="Present" <?=$v==='Present'?'checked':''?>> <span class="pchoice">✓ Present</span></label><label><input type="radio" name="status[<?=$r['id']?>]" value="Absent" <?=$v==='Absent'?'checked':''?>> <span class="achoice">× Absent</span></label></div></td></tr><?php endwhile;else:?><tr><td colspan="3" class="empty">Add students before marking attendance.</td></tr><?php endif;?></tbody></table></div><div class="actions"><span class="muted">Date: <?=e(date('d F Y',strtotime($date)))?></span><button class="btn primary" <?=$rows->num_rows?'':'disabled'?>>Save attendance →</button></div></form></section><?php require 'includes/footer.php';?>